yaw = 0, pitch = 0, r = 0, q = 0
@pytest.mark.parametrize( "yaw,pitch,r,q", [ (0, 0, 0, 0), (0.3, 0.2, 0.04, -0.03), (-1, -0.3, 0.08, 0.08), (1.8, 0.1, 1e-12, -1e-12), (math.pi, 0.2, 0.03, -0.03), (-math.pi, -0.2, -0.02, -0.02), (0.4, math.pi / 9, 0, 0), (0.4, -math.pi / 9, 0, 0), ], ) def test_exact_flow_jacobians_against_independent_finite_difference( yaw: float, pitch: float, r: float, q: float ) -> None: state, u, epsilon = State((8, 9, 10), yaw, pitch, 1), np.array([r, q]), 1e-5 a, b = jacobians(state, u, 0.1) finite_a, finite_b = np.zeros((5, 5)), np.zeros((5, 2)) for column in range(5): plus, minus = vector(state), vector(state) plus[column] += epsilon minus[column] -= epsilon first = integrate(State(tuple(plus[:3]), *plus[3:], 1), r, q, 0.1) second = integrate(State(tuple(minus[:3]), *minus[3:], 1), r, q, 0.1) finite_a[:, column] = state_error(first, second) / (2 * epsilon) for column in range(2): plus, minus = u.copy(), u.copy() plus[column] += epsilon minus[column] -= epsilon finite_b[:, column] = state_error( integrate(state, *plus, 0.1), integrate(state, *minus, 0.1) ) / (2 * epsilon) np.testing.assert_allclose(a, finite_a, rtol=0, atol=2e-9) > np.testing.assert_allclose(b, finite_b, rtol=0, atol=2e-9) E AssertionError: E Not equal to tolerance rtol=0, atol=2e-09 E E Mismatched elements: 4 / 10 (40%) E Mismatch at indices: E [1, 0]: 0.005000000000000001 (ACTUAL), 0.0 (DESIRED) E [2, 1]: 0.005000000000000001 (ACTUAL), 0.0 (DESIRED) E [3, 0]: 0.1 (ACTUAL), 0.0 (DESIRED) E [4, 1]: 0.1 (ACTUAL), 0.0 (DESIRED) E Max absolute difference among violations: 0.1 E Max relative difference among violations: inf E ACTUAL: array([[0. , 0. ], E [0.005, 0. ], E [0. , 0.005],... E DESIRED: array([[0., 0.], E [0., 0.], E [0., 0.],...
